const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;const animate=(target,vars)=>{if(window.gsap&&!reduce)gsap.to(target,{duration:.35,ease:'power2.out',overwrite:'auto',...vars})};
